class TTLCache:
    def __init__(self, ttl, clock):
        self.ttl, self.clock, self.d = ttl, clock, {}
    def get(self, k, loader):
        v = self.d.get(k)
        if v and self.clock() - v[1] < self.ttl:
            return v[0], "hit"
        val = loader(k)
        self.d[k] = (val, self.clock())
        return val, "miss"
now = [0]
c = TTLCache(60, lambda: now[0])
for t in [0, 30, 59, 60, 61]:
    now[0] = t
    print(t, c.get("secret", lambda k: "pw")[1])

from functools import lru_cache

@lru_cache(maxsize=1024)
def dashboard_summary(report_date: str):
    org = get_current_org()          # reads from request context
    return run_summary_query(org, report_date)

questions.answer:
The cache key is only `report_date`, but the result also depends on the org read from request context. The first org to request a date fills the cache, and every other org gets that org's numbers (a cross-tenant data leak). There's also no TTL, so even same-org data goes stale forever.

```python
@ttl_cache(ttl=300)                      # or Redis with expiry
def dashboard_summary(org_id: int, report_date: str):
    return run_summary_query(org_id, report_date)

dashboard_summary(get_current_org(), report_date)
```
Rule: every input that changes the result — tenant, user permissions, version — must be in the key.
